package project.init.framework.error;import lombok.Data;import project.init.framework.utils.enummerate.ESuccessResponse;@Datapublic class BaseResponse {    private int value;    private Object message;    public BaseResponse(int value, Object message) {        this.value = value;        this.message = message;    }    public BaseResponse(ESuccessResponse eSuccessResponse) {        this.value = eSuccessResponse.getValue();        this.message = eSuccessResponse.getMessage();    }}